const CONFIG={url:'',anon:''}; // Fill from assets/js/config.js, never put service_role keys here
const CATS=[['İtlər','dogs','🐶'],['Pişiklər','cats','🐱'],['Quşlar','birds','🦜'],['Balıqlar','fish','🐠'],['Gəmiricilər','rodents','🐹'],['Yemlər','food','🥣'],['Aksesuarlar','accessories','🦴'],['Gigiyena','hygiene','🧴'],['Baxım','grooming','✂️']];
const SAMPLE=[['İt yemi Premium 2 kq',35,'dogs','🥣'],['Pişik yemi Kitten 2 kq',42,'cats','🐈'],['Quş yemi 1 kq',8,'birds','🌾'],['Akvarium filtri',36,'fish','🐟'],['Gəmirici evi',24,'rodents','🏠'],['İt boyunluğu',14,'accessories','🦮'],['Pişik qumu 10 L',12,'hygiene','🧴'],['Oyuncaq top',7,'accessories','🎾'],['Akvarium dekoru',18,'fish','🪸'],['Dovşan yemi',10,'food','🥕']].map((x,i)=>({id:'demo-'+i,name:x[0],price:x[1],category:x[2],emoji:x[3],stock:10,active:true,image_url:''}));
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>(Number(n)||0).toFixed(2)+' ₼';
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem('bzh_'+k))??d}catch{return d}};const write=(k,v)=>localStorage.setItem('bzh_'+k,JSON.stringify(v));
let discountOnly=false;let isAdmin=false;let db=null,user=null,profile=null,products=[],delivery=[],orders=[],bookings=[],currentPage='home',filterCat='',searchTerm='',selectedProduct=null,adminTab='overview';
const DEMO=!(window.BZH_CONFIG?.supabaseUrl&&window.BZH_CONFIG?.supabaseAnonKey&&window.supabase);
if(!DEMO)db=window.supabase.createClient(window.BZH_CONFIG.supabaseUrl,window.BZH_CONFIG.supabaseAnonKey);
const storage={get products(){return read('products',SAMPLE)},set products(v){write('products',v)},get orders(){return read('orders',[])},set orders(v){write('orders',v)},get delivery(){return read('delivery',[{region:'Bərdə',fee:0},{region:'Ağdam',fee:5},{region:'Tərtər',fee:4},{region:'Yevlax',fee:5},{region:'Digər',fee:10}])},set delivery(v){write('delivery',v)}};
const cart=()=>read('cart',[]).filter(i=>products.some(p=>p.id===i.id));const fav=()=>read('fav',[]).filter(id=>products.some(p=>p.id===id));function toast(s){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=s;document.body.append(el);setTimeout(()=>el.remove(),2700)}
async function init(){if(DEMO){products=[];delivery=[];orders=[];toast('Bağlantı konfiqurasiyası yoxlanmalıdır')}else{const a=await db.auth.getUser();user=a.data.user; if(user){let r=await db.from('profiles').select('*').eq('id',user.id).maybeSingle();profile=r.data;let ar=await db.from('admins').select('user_id').eq('user_id',user.id).maybeSingle();isAdmin=!!ar.data} await reloadProducts();await reloadDelivery();await loadRecords()}bindShell();document.querySelectorAll('.admin-link').forEach(x=>x.hidden=!isAdmin);route();window.addEventListener('hashchange',route);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});setTimeout(()=>{let x=$('#splash');if(x){x.style.opacity=0;setTimeout(()=>x.remove(),400)}},650)}
async function reloadProducts(){if(DEMO){products=[];return}let r=await db.from('products').select('id,name,price,category,stock,active,image_url,description,unit,unit_quantity,old_price').eq('active',true).order('created_at',{ascending:false}).limit(20);products=r.data||[];if(!r.error){write('cart',read('cart',[]).filter(i=>products.some(p=>p.id===i.id)));write('fav',read('fav',[]).filter(id=>products.some(p=>p.id===id)))}if(r.error)toast(r.error.message)}
async function reloadDelivery(){if(DEMO){delivery=[];return}let r=await db.from('delivery_zones').select('region,fee').eq('active',true).order('region');delivery=r.data||[]}
async function loadRecords(){if(!db||!user)return;const [o,b]=await Promise.all([db.from('orders').select('*').order('created_at',{ascending:false}).limit(20),db.from('grooming_bookings').select('*').order('created_at',{ascending:false}).limit(20)]);if(!o.error)orders=o.data||[];if(!b.error)bookings=b.data||[]}
function bindShell(){$('#appSearch').oninput=e=>{searchTerm=e.target.value;location.hash='catalog';render()};$('#appSearchMobile').oninput=e=>{searchTerm=e.target.value;location.hash='catalog';render()}}
const link=(p)=>`#${p}`;const catCard=c=>`<a class="category" href="#catalog?cat=${c[1]}"><img src="assets/images/${c[1]}.jpg" alt="${esc(c[0])}" loading="lazy"><strong>${esc(c[0])}</strong></a>`;
const unitText=p=>`${Number(p.unit_quantity)||1} ${p.unit||'ədəd'}`;const hasDiscount=p=>Number(p.old_price)>Number(p.price)&&Number(p.price)>=0;const discountLabel=p=>hasDiscount(p)?`<span class="discount-pill">−${Math.round((1-p.price/p.old_price)*100)}%</span>`:'';const priceMarkup=p=>`<strong class="price">${money(p.price)}</strong>${hasDiscount(p)?`<del class="old-price">${money(p.old_price)}</del>`:''}`;function productCard(p){return `<article class="product ${Number(p.stock)<=0?'out-of-stock':''} ${hasDiscount(p)?'on-sale':''}">${discountLabel(p)}<button class="heart" data-act="fav" data-id="${esc(p.id)}">${fav().includes(p.id)?'♥':'♡'}</button><a href="#product?id=${encodeURIComponent(p.id)}"><div class="photo">${p.image_url?`<img loading="lazy" src="${esc(p.image_url)}" alt="${esc(p.name)}">`:'<img src="assets/images/brand-logo.png" alt="" class="placeholder-img">'}</div></a><div class="details"><h3>${esc(p.name)}</h3><span class="muted">${esc(unitText(p))} · ${p.stock>0?'Stokda var':'<b class="sold-out-text">Bitib</b>'}</span><div class="productfoot">${priceMarkup(p)}<button class="circleadd" data-act="add" data-id="${esc(p.id)}" ${p.stock<=0?'disabled':''}>+</button></div></div></article>`}
const header=(s)=>`<div class="sectionhead"><h2>${s}</h2></div>`;
function home(){return `<div class="hero"><div class="hero-copy"><h1>Dostlarınız üçün ən yaxşısı!</h1><p>Keyfiyyətli yemlər, aksesuarlar və ev heyvanlarınız üçün hər şey bir yerdə.</p><button class="btn secondary" onclick="location.hash='catalog'">Məhsullara bax →</button></div><div class="heroart heroart-home"><img src="assets/images/ana_ekran_yuxari_resim.png" alt="Ev heyvanları"></div></div>${header('Kateqoriyalar')}<div class="categories">${CATS.map(catCard).join('')}</div>${header('Seçilmiş məhsullar')}<div class="grid">${products.filter(p=>p.active!==false).slice(0,10).map(productCard).join('')}</div>${header('Kompleks baxım')}<div class="home-feature-grid"><div class="panel twocol home-care"><div class="care-copy"><h2>İt və pişiklər üçün baxım</h2><p>Yuyunma, daranma, tük kəsimi və gigiyena xidmətləri.</p><a class="btn" href="#grooming">Rezervasiya et</a></div><div class="heroart heroart-care"><img src="assets/images/ana_ekran_asagi_baxim.png" alt="İt və pişik baxımı"></div></div><section class="panel partners-card" aria-label="Brendlər"><h2>Brendlər</h2><div class="partners-viewport"><div class="partners-track"><div class="partner-slot"><img src="assets/emekdaslar/emekdas-1.jpg" alt="Əməkdaş 1 loqosu" loading="lazy"></div><div class="partner-slot"><img src="assets/emekdaslar/emekdas-2.jpg" alt="Əməkdaş 2 loqosu" loading="lazy"></div><div class="partner-slot"><img src="assets/emekdaslar/emekdas-3.jpg" alt="Əməkdaş 3 loqosu" loading="lazy"></div><div class="partner-slot"><img src="assets/emekdaslar/emekdas-4.jpg" alt="Əməkdaş 4 loqosu" loading="lazy"></div><div class="partner-slot"><img src="assets/emekdaslar/emekdas-5.jpg" alt="Əməkdaş 5 loqosu" loading="lazy"></div><div class="partner-slot"><img src="assets/emekdaslar/emekdas-6.jpg" alt="Əməkdaş 6 loqosu" loading="lazy"></div></div></div></section></div>`}
function catalog(){let arr=products.filter(p=>p.active!==false&&(!filterCat||p.category===filterCat)&&(!searchTerm||p.name.toLowerCase().includes(searchTerm.toLowerCase()))&&(!discountOnly||hasDiscount(p)));return `${header('Məhsul kataloqu')}<div class="filters"><select id="catFilter"><option value="">Bütün kateqoriyalar</option>${CATS.map(c=>`<option value="${c[1]}" ${filterCat===c[1]?'selected':''}>${c[0]}</option>`).join('')}</select><select id="sortProducts"><option value="">Sıralama</option><option value="cheap">Əvvəl ucuz</option><option value="expensive">Əvvəl baha</option><option value="name">Ada görə</option></select><label class="discount-filter"><input type="checkbox" id="discountOnly" ${discountOnly?'checked':''}> Endirimli məhsullar</label></div><div id="productGrid" class="grid">${arr.map(productCard).join('')||'<div class="empty">Məhsul tapılmadı</div>'}</div>`}
function detail(){let p=products.find(x=>x.id===new URLSearchParams(location.hash.split('?')[1]).get('id'));if(!p)return '<div class="empty">Məhsul tapılmadı</div>';let related=products.filter(x=>x.id!==p.id&&x.active!==false).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category));return `<div class="detail-layout"><div class="detail-left"><div class="photo detail-photo">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}">`:'<img src="assets/images/brand-logo.png" alt="" class="placeholder-img">'}${hasDiscount(p)?`<div class="detail-discount">${discountLabel(p)}</div>`:''}<button class="detail-fav" aria-label="Sevimlilərə əlavə et" data-act="fav" data-id="${esc(p.id)}">${fav().includes(p.id)?'♥':'♡'}</button><button class="detail-add" aria-label="Səbətə əlavə et" data-act="add" data-id="${esc(p.id)}" ${p.stock<=0?'disabled':''}>+</button></div><div class="panel detail-info"><span class="badge">${esc(CATS.find(c=>c[1]===p.category)?.[0]||p.category)}</span><h1>${esc(p.name)}</h1><div class="detail-price">${priceMarkup(p)}</div><p class="muted">Ölçü vahidi: ${esc(unitText(p))}</p><p>${esc(p.description||'Məhsul haqqında ətraflı məlumat mağaza tərəfindən əlavə olunacaq.')}</p><p class="${p.stock<=0?'sold-out-text':''}">${p.stock>0?'🟢 Stokda var':'Bitib'}</p></div></div><section class="detail-right" aria-label="Digər məhsullar"><div class="grid detail-related-grid">${related.map(productCard).join('')||'<p class="muted">Başqa məhsul yoxdur</p>'}</div></section></div>`}

function cartPage(){let items=cart();let sum=0;let valid=items.map(it=>{let p=products.find(x=>x.id===it.id);if(!p)return '';sum+=p.price*it.qty;return `<div class="cart-item"><a class="cart-thumb" href="#product?id=${encodeURIComponent(p.id)}"><img src="${esc(p.image_url||'assets/images/brand-logo.png')}" alt="${esc(p.name)}" loading="lazy"></a><div class="cart-info"><a href="#product?id=${encodeURIComponent(p.id)}" class="cart-name">${esc(p.name)}</a><span class="muted">${esc(unitText(p))} · ${money(p.price)} ${hasDiscount(p)?`<span class="cart-discount">Endirim −${Math.round((1-p.price/p.old_price)*100)}%</span> <del>${money(p.old_price)}</del>`:''}</span><strong class="price">${money(p.price*it.qty)}</strong></div><div class="cart-controls"><input aria-label="Miqdar" class="quantity" type="number" min="1" max="${p.stock}" value="${it.qty}" data-qty="${esc(p.id)}"><button class="btn secondary" data-act="remove" data-id="${esc(p.id)}">Sil</button></div></div>`}).filter(Boolean).join('');return `${header('Səbətim')}<div class="panel cart-panel">${valid||'<div class="empty">Səbətiniz boşdur</div>'}${valid?`<div class="cart-summary"><span>Cəmi</span><strong class="price">${money(sum)}</strong></div><a class="btn cart-checkout" href="#checkout">Sifarişi rəsmiləşdir</a>`:''}</div>`}

function authForm(mode){let register=mode==='register';return `<div class="panel" style="max-width:520px;margin:auto"><h2>${register?'Qeydiyyat':mode==='forgot'?'Parolu bərpa et':'Daxil ol'}</h2><form id="authForm">${register?`<div class="twocol"><div class="field"><label>Ad *</label><input name="first_name" required></div><div class="field"><label>Soyad *</label><input name="last_name" required></div></div><div class="twocol compact-pair"><div class="field"><label>Telefon *</label><input name="phone" type="tel" placeholder="+994 XX XXX XX XX" required></div><div class="field"><label>Rayon / şəhər *</label><select name="region" required>${regions.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div><div class="field"><label>Tam ünvan *</label><textarea name="address" required></textarea></div>`:''}<div class="field"><label>E-poçt *</label><input type="email" name="email" required></div>${mode!=='forgot'?'<div class="field"><label>Parol *</label><input type="password" name="password" minlength="8" required></div>':''}<button class="btn" type="submit">${register?'Qeydiyyatdan keç':mode==='forgot'?'Bərpa linki göndər':'Daxil ol'}</button></form><p><a href="#login">Giriş</a> · <a href="#register">Qeydiyyat</a> · <a href="#forgot">Parolu unutdum</a></p></div>`}
const regions=['Bərdə','Ağdam','Tərtər','Yevlax','Ağcabədi','Bakı','Gəncə','Sumqayıt','Mingəçevir','Şirvan','Lənkəran','Şəki','Quba','Qusar','Xaçmaz','Şamaxı','İsmayıllı','Göyçay','Ucar','Zərdab','Saatlı','Sabirabad','İmişli','Beyləqan','Füzuli','Cəbrayıl','Zəngilan','Qubadlı','Laçın','Kəlbəcər','Şuşa','Xankəndi','Xocalı','Xocavənd','Ağdərə','Naftalan','Goranboy','Samux','Göygöl','Daşkəsən','Gədəbəy','Tovuz','Şəmkir','Qazax','Ağstafa','Balakən','Zaqatala','Qax','Oğuz','Qəbələ','Kürdəmir','Hacıqabul','Salyan','Neftçala','Biləsuvar','Cəlilabad','Masallı','Astara','Lerik','Yardımlı','Siyəzən','Şabran','Xızı','Abşeron','Ordubad','Naxçıvan','Babək','Culfa','Kəngərli','Şahbuz','Sədərək','Digər'];
function checkout(){let items=cart();if(!items.length)return '<div class="empty">Səbət boşdur</div>';let sum=items.reduce((a,i)=>a+(products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `${header('Sifarişi rəsmiləşdir')}<div class="twocol"><form id="checkoutForm" class="panel checkout-form"><div class="field"><label>Ad və soyad</label><input name="customer_name" value="${esc((profile?.first_name||'')+' '+(profile?.last_name||''))}" required></div><div class="field"><label>Telefon</label><input name="phone" type="tel" value="${esc(profile?.phone||'')}" required></div><div class="field"><label>Rayon</label><select name="region" id="regionSelect">${delivery.map(d=>`<option value="${esc(d.region)}">${esc(d.region)}</option>`).join('')}</select></div><div class="field checkout-wide"><label>Ünvan</label><textarea name="address" required>${esc(profile?.address||'')}</textarea></div><div class="field checkout-wide"><label>Qeyd</label><textarea name="note"></textarea></div><div class="field"><label>Ödəniş üsulu</label><select name="payment_method"><option value="cash">Çatdırılmada ödəniş</option><option value="whatsapp">WhatsApp ilə razılaşdırma</option><option value="card" disabled>Kapital Bank (sonra)</option></select></div><button class="btn" type="submit">Sifarişi yarat</button></form><div class="panel"><h3>Sifariş xülasəsi</h3>${items.map(i=>{let p=products.find(p=>p.id===i.id);return `<div class="line row"><span>${esc(p?.name)} × ${i.qty}</span><b>${money((p?.price||0)*i.qty)}</b></div>`}).join('')}<div class="line row"><span>Məhsullar</span><b>${money(sum)}</b></div><div class="line row"><span>Çatdırılma</span><b id="deliveryFee">${money(delivery[0]?.fee||0)}</b></div><h3 id="checkoutTotal">Cəmi: ${money(sum+(+delivery[0]?.fee||0))}</h3></div></div>`}
function orderDetail(o,adminView=false){let lines=Array.isArray(o.items)?o.items:typeof o.items==='string'?(()=>{try{return JSON.parse(o.items)}catch{return []}})():[];return `<details class="order-details"><summary>📦 Sifariş detalları</summary><div class="order-detail-content">${lines.map(i=>{const p=products.find(x=>String(x.id)===String(i.product_id||i.id));const qty=Number(i.qty||i.quantity||1);const price=Number(i.price??p?.price??0);const img=i.image_url||p?.image_url;return `<div class="order-line">${img?`<img src="${esc(img)}" alt="" loading="lazy">`:'<span class="order-noimage">📦</span>'}<div><strong>${esc(i.name||p?.name||'Məhsul')}</strong><div>${qty} × ${money(price)}</div>${Number(i.old_price)>price?`<small>Endirimli qiymət</small>`:''}</div><b>${money(qty*price)}</b></div>`}).join('')||'<p>Məhsul detalları saxlanılmayıb.</p>'}<div class="order-totals"><p>Məhsullar: <b>${money(o.subtotal??(Number(o.total||0)-Number(o.delivery_fee||0)))}</b></p><p>Çatdırılma: <b>${money(o.delivery_fee||0)}</b></p><p>Cəmi: <b>${money(o.total||0)}</b></p></div>${adminView?`<div class="order-customer"><p><b>Sifariş:</b> ${esc(o.order_number||o.id)}</p><p><b>Müştəri:</b> ${esc(o.customer_name||'')}</p><p><b>Telefon:</b> ${esc(o.phone||'')}</p><p><b>Rayon:</b> ${esc(o.region||'')}</p><p><b>Ünvan:</b> ${esc(o.address||'')}</p><p><b>Qeyd:</b> ${esc(o.note||'—')}</p><p><b>Ödəniş:</b> ${esc(o.payment_method||'Qeyd edilməyib')}</p><p><b>Tarix:</b> ${o.created_at?new Date(o.created_at).toLocaleString('az-AZ'):''}</p></div><button type="button" class="btn secondary" data-act="printorder" data-id="${esc(o.id)}">🖨 Çeki çap et</button>`:''}</div></details>`}
function orderPage(){let rows=DEMO?storage.orders:orders;return `${header('Sifarişlərim')}<div class="panel">${rows.length?rows.map(o=>`<div class="line"><div class="row"><b>#${esc(o.order_number||o.id?.slice(0,8))}</b><span class="status ${esc(o.status)}">${statusName(o.status)}</span></div><p>${money(o.total)} · ${esc(o.region)} · ${new Date(o.created_at).toLocaleString('az-AZ')}</p>${orderDetail(o)}${o.status==='pending'?`<button class="btn secondary" data-act="cancelorder" data-id="${esc(o.id)}">Sifarişi ləğv et</button>`:''}</div>`).join(''):'<div class="empty">Sifariş yoxdur</div>'}</div>`}
const statusName=s=>({pending:'Gözləyir',completed:'Tamamlandı',cancelled:'Ləğv edildi',confirmed:'Təsdiqləndi'})[s]||s;
function grooming(){return `${header('Kompleks baxım')}<div class="hero"><div><h1>Dostunuzun baxımı bizə əmanət!</h1><p>İt və pişiklər üçün yuyunma, tük kəsimi, daranma və gigiyena.</p></div><div class="heroart grooming-hero-art"><img src="assets/images/baxim_rezervasiya2.png" alt="Baxım"></div></div><div class="panel grooming-panel" style="margin-top:16px"><h2>Baxım rezervasiyası</h2><form id="bookingForm"><div class="booking-fields"><div class="field"><label>Heyvan</label><select name="pet_type"><option>İt</option><option>Pişik</option></select></div><div class="field"><label>Heyvanın adı</label><input name="pet_name" required></div><div class="field"><label>Xidmət</label><select name="service"><option>Kompleks baxım</option><option>Yuyunma və qurutma</option><option>Tük kəsimi və daranma</option><option>Dırnaq və gigiyena</option></select></div><div class="field"><label>Tarix</label><input type="date" name="date" min="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Arzu olunan saat</label><input type="time" name="time" required></div><div class="field"><label>Telefon</label><input name="phone" type="tel" required></div></div><div class="field booking-note"><label>Qeyd</label><textarea name="note"></textarea></div><p class="notice">Vaxt və qiymət mağaza tərəfindən təsdiqlənəcək; bu forma avtomatik boş saat zəmanəti vermir.</p><button class="btn" type="submit">Rezervasiya sorğusu göndər</button></form></div>`}
function profilePage(){const meta=user?.user_metadata||{};const first=profile?.first_name||meta.first_name||meta.name||'';const last=profile?.last_name||meta.last_name||'';const phone=profile?.phone||meta.phone||user?.phone||'';return `${header('Profilim')}<div class="panel profile-card"><div class="profile-heading"><span class="profile-avatar">${esc((first||user?.email||'M').charAt(0).toUpperCase())}</span><div><h3>${esc(([first,last].filter(Boolean).join(' '))||'İstifadəçi')}</h3><span class="muted">${isAdmin?'Admin':'Müştəri'} · Şəxsi hesab məlumatları</span></div></div><div class="profile-info"><p><b>Ad:</b> ${esc(first)||'—'}</p><p><b>Soyad:</b> ${esc(last)||'—'}</p><p><b>E-poçt:</b> ${esc(user?.email||'—')}</p><p><b>Telefon:</b> ${esc(phone)||'—'}</p></div><div class="actions">${isAdmin?'<a class="btn" href="#admin">Admin panelə keç</a>':''}<a class="btn secondary" href="#orders">Sifariş tarixçəm</a><a class="btn secondary" href="#care-history">Baxım tarixçəm</a><a class="btn secondary" href="#grooming">Baxım rezervasiyası</a><a class="btn secondary" href="#settings">Tənzimləmələr</a></div>${user?'<p><button class="btn outline" data-act="logout">Çıxış</button></p>':'<p><a class="btn" href="#login">Daxil ol</a></p>'}</div>`}
function careHistory(){const rows=bookings.filter(b=>b.user_id===user?.id);return `${header('Baxım tarixçəm')}<div class="panel">${rows.length?rows.map(b=>`<div class="line"><div class="row"><strong>${esc(b.pet_name||b.pet_type||'Heyvan')}</strong><span class="status ${esc(b.status||'pending')}">${esc(statusName(b.status||'pending'))}</span></div><div class="muted">${esc(b.service||'Baxım')} · ${esc(b.date||'')} ${esc(b.time||'')}</div></div>`).join(''):'<div class="empty">Hələ baxım rezervasiyanız yoxdur</div>'}</div>`}
function settings(){return `${header('Hesab parametrləri')}<div class="panel"><h3>Şəxsi məlumatlar</h3><form id="settingsForm"><div class="twocol"><div class="field"><label>Ad</label><input name="first_name" value="${esc(profile?.first_name||'')}" required></div><div class="field"><label>Soyad</label><input name="last_name" value="${esc(profile?.last_name||'')}" required></div><div class="field"><label>Telefon</label><input name="phone" value="${esc(profile?.phone||'')}"></div><div class="field checkout-wide"><label>Ünvan</label><textarea name="address">${esc(profile?.address||'')}</textarea></div><button class="btn">Yadda saxla</button></form><button class="btn outline" data-act="deleteaccount">Hesabı silmək üçün sorğu</button></div>`}
function admin(){if(!isAdmin)return '<div class="panel">Bu bölməyə giriş üçün administrator səlahiyyəti tələb olunur.</div>';return `${header('Admin idarəetməsi')}<div class="adminnav">${[['overview','İcmal'],['products','Məhsullar'],['orders','Sifarişlər'],['delivery','Çatdırılma'],['bookings','Baxım'],['users','İstifadəçilər']].map(x=>`<button data-admin="${x[0]}" class="${adminTab===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><div id="adminBody">${adminBody()}</div>`}
function adminBody(){if(adminTab==='overview')return `<div class="grid">${[['Məhsullar',products.length],['Sifarişlər',(DEMO?storage.orders:orders).length],['Gözləyən',(DEMO?storage.orders:orders).filter(x=>x.status==='pending').length],['Rezervasiyalar',bookings.length]].map(x=>`<div class="panel"><h3>${x[1]}</h3><span>${x[0]}</span></div>`).join('')}</div>`;
if(adminTab==='products')return `<div class="panel"><h3>Məhsul əlavə et / redaktə et</h3><form id="productForm"><input type="hidden" name="id"><div class="twocol"><div class="field"><label>Məhsul adı</label><input name="name" required></div><div class="field"><label>Qiymət ₼</label><input name="price" type="number" min="0" step=".01" required></div><div class="field"><label>Kateqoriya</label><select name="category">${CATS.map(c=>`<option value="${c[1]}">${c[0]}</option>`).join('')}</select></div><div class="field"><label>Stok</label><input name="stock" type="number" min="0" required></div></div><div class="twocol compact-pair"><div class="field"><label>Ölçü vahidi</label><select name="unit">${['ədəd','kq','qram','litr','ml','paket','qutu','dəst','metr','cüt'].map(u=>`<option value="${u}">${u}</option>`).join('')}</select></div><div class="field"><label>Bir məhsulun miqdarı</label><input type="number" name="unit_quantity" min="0.001" step="any" value="1" required></div><div class="field"><label>Endirimdən əvvəlki qiymət ₼ (istəyə bağlı)</label><input name="old_price" type="number" min="0" step=".01" placeholder="Məsələn 15.00"></div></div><div class="field"><label>Təsvir</label><textarea name="description"></textarea></div><div class="field"><label>Məhsul şəkli</label><input type="file" name="image_file" accept="image/*" class="bzh-file-input" id="bzhProductImage"><label for="bzhProductImage" class="bzh-file-label">🖼 Şəkil seç <span id="bzhFileName">Fayl seçilməyib</span></label><button type="button" class="btn secondary" id="bzhOpenCamera">📷 Kamera</button><small class="muted">Şəkil avtomatik çevrilir və WebP formatında sıxılır.</small><input type="hidden" name="image_url"></div><button class="btn" type="submit">Yadda saxla</button> <button type="reset" class="btn secondary">Təmizlə</button></form><h3>Məhsullar</h3><div class="tablewrap"><table><tr><th>Ad</th><th>Qiymət</th><th>Stok</th><th>Əməliyyat</th></tr>${products.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><button class="btn secondary" data-act="editproduct" data-id="${esc(p.id)}">Redaktə</button> <button class="btn outline" data-act="deleteproduct" data-id="${esc(p.id)}">Sil</button></td></tr>`).join('')}</table></div></div>`;
if(adminTab==='delivery')return `<div class="panel"><h3>Rayonlara çatdırılma qiymətləri</h3><form id="deliveryForm"><div class="twocol"><div class="field"><label>Rayon</label><select name="region">${regions.map(r=>`<option>${esc(r)}</option>`).join('')}</select></div><div class="field"><label>Çatdırılma haqqı ₼</label><input type="number" name="fee" min="0" step=".01" required></div></div><button class="btn">Qiyməti yadda saxla</button></form><div class="tablewrap"><table><tr><th>Rayon</th><th>Çatdırılma</th><th></th></tr>${delivery.map(d=>`<tr><td>${esc(d.region)}</td><td>${money(d.fee)}</td><td><button class="btn secondary" data-act="deletedelivery" data-id="${esc(d.region)}">Sil</button></td></tr>`).join('')}</table></div></div>`;
if(adminTab==='orders')return `<div class="panel"><h3>Sifarişlərin idarə olunması</h3><div class="tablewrap"><table><tr><th>Sifariş</th><th>Müştəri</th><th>Telefon</th><th>Rayon</th><th>Ünvan</th><th>Məbləğ</th><th>Status</th></tr>${(DEMO?storage.orders:orders).map(o=>`<tr class="admin-order-row ${esc(o.status||'pending')}"><td>${esc(o.order_number||o.id?.slice(0,8))}${orderDetail(o,true)}</td><td>${esc(o.customer_name)}</td><td>${esc(o.phone)}</td><td>${esc(o.region)}</td><td>${esc(o.address)}</td><td>${money(o.total)}</td><td><select data-order-status="${esc(o.id)}">${['pending','completed','cancelled'].map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${statusName(s)}</option>`).join('')}</select></td></tr>`).join('')}</table></div></div>`;
if(adminTab==='bookings')return `<div class="panel"><h3>Baxım rezervasiyaları</h3><div class="tablewrap"><table><tr><th>Heyvan</th><th>Xidmət</th><th>Tarix</th><th>Telefon</th><th>Status</th></tr>${bookings.map(b=>`<tr><td>${esc(b.pet_name)} (${esc(b.pet_type)})</td><td>${esc(b.service)}</td><td>${esc(b.date)} ${esc(b.time)}</td><td>${esc(b.phone)}</td><td><select data-booking-status="${esc(b.id)}">${['pending','confirmed','completed','cancelled'].map(s=>`<option value="${s}" ${b.status===s?'selected':''}>${statusName(s)}</option>`).join('')}</select></td></tr>`).join('')}</table></div></div>`;
return `<div class="panel"><h3>İstifadəçilər</h3><p>İstifadəçi siyahısına giriş üçün ayrıca təhlükəsiz server icazəsi tələb olunur.</p></div>`}
function route(){let hash=location.hash.slice(1)||'home';let [page,query]=hash.split('?');if(query&&new URLSearchParams(query).has('cat'))filterCat=new URLSearchParams(query).get('cat');currentPage=page;if(page==='admin'&&!isAdmin){currentPage=user?'profile':'login';location.hash=currentPage;return}render();window.scrollTo({top:0,behavior:'instant'})}
function render(){let page=currentPage;let content=({home,catalog,product:detail,cart:cartPage,checkout,login:()=>authForm('login'),register:()=>authForm('register'),forgot:()=>authForm('forgot'),orders:orderPage,profile:profilePage,"care-history":careHistory,settings,grooming,admin,favorites:()=>`${header('Sevimlilər')}<div class="grid">${products.filter(p=>fav().includes(p.id)).map(productCard).join('')||'<div class="empty">Sevimli məhsul yoxdur</div>'}</div>`,privacy:()=>`${header('Məxfilik siyasəti')}<div class="panel"><p>Hesab və sifariş məlumatları xidmətin göstərilməsi üçün emal olunur. Əlaqə: WhatsApp +994 51 714 09 00.</p></div>`,terms:()=>`${header('İstifadə şərtləri')}<div class="panel"><p>Sifariş və baxım sorğularının mövcudluğu və qiyməti mağaza tərəfindən təsdiqlənir.</p></div>`,animals:()=>`${header('Canlı heyvanlar')}<div class="panel"><p>Canlı heyvanlar barədə məlumat və mövcudluq üçün mağaza ilə əlaqə saxlayın.</p><a class="btn green" href="https://wa.me/994517140900">WhatsApp ilə əlaqə</a></div>`})[page];$('#content').innerHTML=content?content():`<div class="panel"><h2>${esc(page)}</h2><p>Məlumat üçün mağaza ilə əlaqə saxlayın.</p></div>`;document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#cartCount').textContent=cart().reduce((a,i)=>a+i.qty,0);if(page==='catalog'){let f=$('#catFilter'),sort=$('#sortProducts');f.onchange=e=>{filterCat=e.target.value;render()};$('#discountOnly').onchange=e=>{discountOnly=e.target.checked;render()};sort.onchange=e=>{products.sort((a,b)=>e.target.value==='cheap'?a.price-b.price:e.target.value==='expensive'?b.price-a.price:a.name.localeCompare(b.name));render()}}if(page==='checkout')$('#regionSelect').onchange=updateTotal;enhanceBzhSelects();if(page==='admin'&&adminTab==='products'){const form=$('#productForm');if(form){form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();submitProduct(form)},false)}}}
function updateTotal(){let reg=$('#regionSelect')?.value;let fee=+(delivery.find(d=>d.region===reg)?.fee||0);let total=cart().reduce((a,i)=>a+(products.find(p=>p.id===i.id)?.price||0)*i.qty,0);$('#deliveryFee').textContent=money(fee);$('#checkoutTotal').textContent='Cəmi: '+money(total+fee)}
function addCart(id){let p=products.find(x=>x.id===id);if(!p||p.stock<=0)return toast('Stokda yoxdur');let a=cart(),i=a.find(x=>x.id===id);if(i){if(i.qty>=p.stock)return toast('Stok limiti');i.qty++}else a.push({id,qty:1});write('cart',a);toast('Səbətə əlavə edildi');render()}
async function handleClick(e){let b=e.target.closest('[data-act]');if(!b)return;let a=b.dataset.act,id=b.dataset.id;if(a==='printorder'){
 const o=orders.find(x=>String(x.id)===String(id));if(!isAdmin||!o)return;
 const lines=Array.isArray(o.items)?o.items:(()=>{try{return JSON.parse(o.items||'[]')}catch{return []}})();
 const pay={cash:'Çatdırılmada nağd ödəniş',whatsapp:'WhatsApp ilə razılaşdırma',card:'Bank kartı'};
 const rows=lines.map((i,n)=>{const p=products.find(x=>String(x.id)===String(i.product_id||i.id));const q=Number(i.qty||i.quantity||1),price=Number(i.price??p?.price??0);return `<tr><td>${n+1}</td><td><b>${esc(i.name||p?.name||'Məhsul')}</b><small>${esc(i.unit_quantity||p?.unit_quantity||1)} ${esc(i.unit||p?.unit||'ədəd')}</small></td><td>${money(price)}</td><td>${q}</td><td><b>${money(price*q)}</b></td></tr>`}).join('');
 const subtotal=Number(o.subtotal??(Number(o.total||0)-Number(o.delivery_fee||0)));
 const w=window.open('','_blank');if(!w)return toast('Çap pəncərəsinə icazə verin');
 w.document.write(`<!doctype html><html lang="az"><head><meta charset="utf-8"><title>Sifariş ${esc(o.order_number||'')}</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#222;margin:0}.receipt{max-width:180mm;margin:auto}.head{text-align:center;border-bottom:2px solid #f70;padding-bottom:14px}.head img{height:76px;max-width:120px;object-fit:contain}.head h2{margin:6px 0;color:#f70}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}.meta div{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}th{text-align:left;background:#fff1e5}td,th{padding:10px 6px;border-bottom:1px solid #ddd;vertical-align:top}td:last-child,th:last-child{text-align:right}small{display:block;color:#777;margin-top:4px}.totals{margin:14px 0 0 auto;max-width:290px}.totals p{display:flex;justify-content:space-between;gap:15px}.grand{font-size:17px;font-weight:bold;border-top:2px solid #f70;padding-top:12px}.thanks{text-align:center;border-top:1px dashed #aaa;padding-top:18px;margin-top:26px;font-weight:bold;color:#e65d00}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="receipt"><div class="head"><img src="${new URL('assets/images/brand-logo.png',location.href).href}" alt="Bərdə ZOO House"><h2>Bərdə ZOO House</h2><strong>SİFARİŞ YIĞIM ÇEKİ</strong></div><div class="meta"><div><b>Sifariş №:</b> ${esc(o.order_number||o.id)}<br><b>Tarix:</b> ${o.created_at?new Date(o.created_at).toLocaleString('az-AZ'):''}<br><b>Ödəniş:</b> ${esc(pay[o.payment_method]||o.payment_method||'Göstərilməyib')}</div><div><b>Müştəri:</b> ${esc(o.customer_name||'')}<br><b>Telefon:</b> ${esc(o.phone||'')}<br><b>Rayon:</b> ${esc(o.region||'')}<br><b>Ünvan:</b> ${esc(o.address||'')}</div></div><table><thead><tr><th>№</th><th>Məhsul / ölçü</th><th>Vahid qiyməti</th><th>Say</th><th>Məbləğ</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><p>Məhsulların cəmi <b>${money(subtotal)}</b></p><p>Çatdırılma <b>${money(o.delivery_fee||0)}</b></p><p class="grand">ÜMUMİ MƏBLƏĞ <b>${money(o.total||0)}</b></p></div><p><b>Qeyd:</b> ${esc(o.note||'Yoxdur')}</p><div class="thanks">Bizi seçdiyiniz üçün təşəkkür edirik!</div></div></body></html>`);
 w.document.close();w.addEventListener('load',()=>{w.focus();w.print()},{once:true});return}
 if(a==='add')addCart(id);if(a==='fav'){let f=fav();f=f.includes(id)?f.filter(x=>x!==id):[...f,id];write('fav',f);render()}if(a==='remove'){write('cart',cart().filter(x=>x.id!==id));render()}if(a==='logout'){if(db)await db.auth.signOut();user=null;profile=null;isAdmin=false;document.querySelectorAll('.admin-link').forEach(x=>x.hidden=true);location.hash='home';toast('Çıxış edildi')}if(a==='deleteaccount')toast('Hesabın silinməsi üçün təhlükəsiz server funksiyası tələb olunur');if(a==='cancelorder'){if(!await customConfirm('Sifarişi ləğv etmək istəyirsiniz?'))return;if(DEMO){let arr=storage.orders,o=arr.find(x=>x.id===id);if(o?.status==='pending'){o.status='cancelled';storage.orders=arr;toast('Sifariş ləğv edildi');render()}}else {const r=await db.from('orders').update({status:'cancelled'}).eq('id',id).eq('user_id',user?.id).eq('status','pending');if(r.error)toast(r.error.message);else{await loadRecords();render();toast('Sifariş ləğv edildi')}}}if(a==='editproduct'){let p=products.find(x=>x.id===id),f=$('#productForm');if(p&&f){['id','name','price','category','stock','description','image_url','unit','unit_quantity','old_price'].forEach(k=>f.elements[k].value=p[k]??'');enhanceBzhSelects();window.scrollTo(0,0)}}if(a==='deleteproduct'){if(!await customConfirm('Məhsul silinsin?'))return;if(DEMO){products=products.filter(x=>x.id!==id);storage.products=products;render()}else {const item=products.find(p=>p.id===id);const r=await db.from('products').delete().eq('id',id).select('id');if(r.error)toast(r.error.message);else if(!r.data?.length)toast('Məhsul silinmədi: icazəni yoxlayın');else{await reloadProducts();render();const cleanup=await removeOwnedProductImage(item?.image_url);toast(cleanup?'Məhsul və şəkli silindi':'Məhsul silindi; şəklin silinməsini yoxlayın')}}}if(a==='deletedelivery'){if(DEMO){delivery=delivery.filter(d=>d.region!==id);storage.delivery=delivery;render()}else {const r=await db.from('delivery_zones').delete().eq('region',id);if(r.error)toast(r.error.message);else{await reloadDelivery();render()}}}}
async function handleSubmit(e){let f=e.target;if(!['checkoutForm','bookingForm','authForm','productForm','deliveryForm','settingsForm'].includes(f.id))return;e.preventDefault();let v=Object.fromEntries(new FormData(f));if(f.id==='authForm'){if(DEMO)return toast('Real giriş üçün Supabase konfiqurasiyası lazımdır');let result;if(currentPage==='register'){result=await db.auth.signUp({email:v.email,password:v.password,options:{data:{first_name:v.first_name,last_name:v.last_name,phone:v.phone,region:v.region,address:v.address}}})}else if(currentPage==='forgot'){result=await db.auth.resetPasswordForEmail(v.email,{redirectTo:location.origin+location.pathname+'#reset'})}else result=await db.auth.signInWithPassword({email:v.email,password:v.password});if(result.error)return toast(result.error.message);toast('Əməliyyat uğurludur; e-poçtunuzu yoxlayın');if(currentPage==='login'){user=result.data.user;const pr=await db.from('profiles').select('*').eq('id',user.id).maybeSingle();profile=pr.data;let ar=await db.from('admins').select('user_id').eq('user_id',user.id).maybeSingle();isAdmin=!!ar.data;document.querySelectorAll('.admin-link').forEach(x=>x.hidden=!isAdmin);location.hash='profile'}return}
if(f.id==='checkoutForm'){if(!db)return toast('Bağlantı yoxdur');if(!user){toast('Sifariş üçün daxil olun');location.hash='login';return}const lines=cart().map(i=>{const p=products.find(x=>x.id===i.id);return p?{product_id:i.id,name:p.name,price:p.price,qty:i.qty,image_url:p.image_url,old_price:p.old_price}:null}).filter(Boolean);if(!lines.length)return toast('Səbət boşdur');const subtotal=lines.reduce((a,x)=>a+x.price*x.qty,0),fee=+(delivery.find(d=>d.region===v.region)?.fee||0);const order={user_id:user.id,customer_name:v.customer_name,phone:v.phone,region:v.region,address:v.address,note:v.note,items:lines,subtotal,delivery_fee:fee,total:subtotal+fee,status:'pending',payment_status:'unpaid'};const r=await db.from('orders').insert(order).select().single();if(r.error)return toast('Sifariş saxlanmadı: '+r.error.message);orders.unshift(r.data);write('cart',[]);location.hash='orders';toast('Sifarişiniz qəbul edildi');return}
if(f.id==='bookingForm'){if(!db)return toast('Bağlantı yoxdur');const r=await db.from('grooming_bookings').insert({...v,user_id:user?.id||null,status:'pending'}).select().single();if(r.error)return toast('Rezervasiya saxlanmadı: '+r.error.message);bookings.unshift(r.data);f.reset();toast('Rezervasiya sorğunuz göndərildi');return}
if(f.id==='productForm'){if(!db||!isAdmin)return toast('Admin girişi tələb olunur');const submitButton=f.querySelector('button[type=submit]');if(submitButton)submitButton.disabled=true;let image_url=v.image_url||null;const file=f.elements.namedItem('image_file')?.files?.[0];if(file){try{const optimized=await optimizeImage(file);const path=`products/${crypto.randomUUID()}.webp`;const up=await db.storage.from('product-images').upload(path,optimized,{contentType:'image/webp',upsert:false});if(up.error)throw up.error;image_url=db.storage.from('product-images').getPublicUrl(path).data.publicUrl}catch(err){if(submitButton)submitButton.disabled=false;return toast('Şəkil yüklənmədi: '+err.message)}}const p={name:v.name,price:+v.price,stock:+v.stock,category:v.category,description:v.description,image_url,active:true};const q=v.id?db.from('products').update(p).eq('id',v.id):db.from('products').insert(p);const r=await q.select().single();if(r.error){if(submitButton)submitButton.disabled=false;return toast('Məhsul saxlanmadı: '+r.error.message)}await reloadProducts();render();toast('Məhsul saxlanıldı');return}
if(f.id==='deliveryForm'){if(!db||!isAdmin)return toast('Admin girişi tələb olunur');const r=await db.from('delivery_zones').upsert({region:v.region,fee:+v.fee,active:true},{onConflict:'region'});if(r.error)return toast(r.error.message);await reloadDelivery();render();toast('Çatdırılma qiyməti saxlanıldı');return}if(f.id==='settingsForm'){if(!user)return toast('Daxil olun');const r=await db.from('profiles').update(v).eq('id',user.id);if(r.error)return toast(r.error.message);profile={...profile,...v};toast('Məlumatlar yeniləndi');return}}
document.addEventListener('click',handleClick);document.addEventListener('submit',e=>{if(e.target?.id==='productForm'){e.preventDefault();return}handleSubmit(e)},true);document.addEventListener('change',e=>{let el=e.target;if(el.dataset.qty){let a=cart(),i=a.find(x=>x.id===el.dataset.qty),p=products.find(x=>x.id===el.dataset.qty);if(i){i.qty=Math.max(1,Math.min(+el.value||1,p.stock));write('cart',a);render()}}if(el.dataset.orderStatus){if(!DEMO){if(!isAdmin)return;db.from('orders').update({status:el.value}).eq('id',el.dataset.orderStatus).then(async r=>{if(r.error)toast(r.error.message);else{await loadRecords();render()}});return}let a=storage.orders,o=a.find(x=>x.id===el.dataset.orderStatus);if(o){o.status=el.value;storage.orders=a;render()}}if(el.dataset.bookingStatus&&!DEMO){if(!isAdmin)return;db.from('grooming_bookings').update({status:el.value}).eq('id',el.dataset.bookingStatus).then(async r=>{if(r.error)toast(r.error.message);else{await loadRecords();render()}});return}if(el.dataset.bookingStatus){let a=read('bookings',[]),o=a.find(x=>x.id===el.dataset.bookingStatus);if(o){o.status=el.value;write('bookings',a);render()}}});document.addEventListener('click',e=>{let b=e.target.closest('[data-admin]');if(b){adminTab=b.dataset.admin;render()}});
const oldRender=render;render=function(){if(currentPage==='success'){let id=new URLSearchParams(location.hash.split('?')[1]).get('id'),o=storage.orders.find(x=>x.id===id);$('#content').innerHTML=`<div class="panel" style="text-align:center;max-width:550px;margin:25px auto"><h1 style="color:var(--green)">✓ Sifariş yaradıldı</h1><p>${esc(o?.order_number||'')}</p><p>WhatsApp üzərindən mağazaya göndərə bilərsiniz.</p><button class="btn green" id="waOrder">WhatsApp-da aç</button><p><a href="#home">Ana səhifəyə qayıt</a></p></div>`;$('#waOrder').onclick=()=>{let msg=`Salam, Bərdə ZOO House! Sifariş: ${o?.order_number}\n${o?.items.map(x=>x.name+' × '+x.qty).join('\n')}\nCəmi: ${money(o?.total)}\n${o?.customer_name}, ${o?.phone}\n${o?.region}, ${o?.address}`;window.open('https://wa.me/994517140900?text='+encodeURIComponent(msg),'_blank')};return}oldRender()};
async function optimizeImage(file){if(!file.type.startsWith('image/'))throw Error('Şəkil seçin');if(file.size>25*1024*1024)throw Error('Maksimum 25 MB');const bmp=await createImageBitmap(file,{imageOrientation:'from-image'});const max=1400,scale=Math.min(1,max/Math.max(bmp.width,bmp.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bmp.width*scale));canvas.height=Math.max(1,Math.round(bmp.height*scale));canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close?.();return await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Şəkil çevrilmədi')),'image/webp',.92))}

// Only remove images inside this application's product-images/products folder.
function ownedProductImagePath(url){try{if(!url)return null;const u=new URL(url,location.href);if(!u.hostname.endsWith('.supabase.co'))return null;const marker='/storage/v1/object/public/product-images/';const n=u.pathname.indexOf(marker);if(n<0)return null;const path=decodeURIComponent(u.pathname.slice(n+marker.length));return /^products\/[a-zA-Z0-9_-]+\.webp$/.test(path)?path:null}catch{return null}}
async function removeOwnedProductImage(url){const path=ownedProductImagePath(url);if(!path)return !url;const r=await db.storage.from('product-images').remove([path]);if(r.error){console.warn('Product image cleanup:',r.error.message);return false}return true}
document.addEventListener('change',e=>{if(e.target?.id==='bzhProductImage'){const label=document.querySelector('#bzhFileName');if(label)label.textContent=e.target.files?.[0]?.name||'Fayl seçilməyib'}});
async function submitProduct(f){
 const button=f.querySelector('button[type="submit"]');if(button?.disabled)return;
 if(!f.checkValidity()){f.reportValidity();return}
 if(!db||!isAdmin){toast('Admin girişi tələb olunur');return}
 const old=button.textContent;button.disabled=true;button.textContent='Saxlanılır...';
 let uploadedPath=null;
 try{
  const v=Object.fromEntries(new FormData(f));let image_url=v.image_url||null;const previousImage=v.id?(products.find(p=>p.id===v.id)?.image_url||null):null;
  const file=f.elements.namedItem('image_file')?.files?.[0];
  if(file){const blob=await optimizeImage(file);uploadedPath=`products/${crypto.randomUUID()}.webp`;
   const up=await db.storage.from('product-images').upload(uploadedPath,blob,{contentType:'image/webp',upsert:false});
   if(up.error)throw new Error('Şəkil yüklənmədi: '+up.error.message);
   image_url=db.storage.from('product-images').getPublicUrl(uploadedPath).data.publicUrl;
  }
  const data={name:String(v.name||'').trim(),price:Number(v.price),stock:Number(v.stock),category:v.category,description:v.description||'',image_url,unit:v.unit||'ədəd',unit_quantity:Number(v.unit_quantity)||1,old_price:v.old_price===''?null:Number(v.old_price),active:true};
  if(data.old_price!==null&&data.old_price<=data.price)throw new Error('Köhnə qiymət yeni qiymətdən böyük olmalıdır');
  if(!data.name||!Number.isFinite(data.price)||!Number.isInteger(data.stock))throw new Error('Məhsul məlumatlarını yoxlayın');
  const query=v.id?db.from('products').update(data).eq('id',v.id):db.from('products').insert(data);
  const result=await query.select('id').single();if(result.error)throw new Error(result.error.message);
  if(previousImage&&uploadedPath&&previousImage!==image_url){const removed=await removeOwnedProductImage(previousImage);if(!removed)toast('Köhnə şəklin Storage-dan silinməsini yoxlayın')}await reloadProducts();render();toast('Məhsul uğurla saxlanıldı');
 }catch(err){if(uploadedPath)await db.storage.from('product-images').remove([uploadedPath]);toast('Məhsul saxlanmadı: '+(err.message||err));let error=f.querySelector('.product-error');
  if(!error){error=document.createElement('p');error.className='product-error';error.setAttribute('role','alert');button.parentNode.insertBefore(error,button)}
  error.textContent='Xəta: '+(err.message||err);
 }finally{button.disabled=false;button.textContent=old}
}

