function customConfirm(message){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='bzh-dialog';overlay.innerHTML=`<div class="bzh-dialog-card" role="dialog" aria-modal="true"><h3>Təsdiq</h3><p></p><div class="actions"><button class="btn secondary" data-answer="no">İmtina</button><button class="btn" data-answer="yes">Təsdiqlə</button></div></div>`;overlay.querySelector('p').textContent=message;function finish(v){overlay.remove();resolve(v)}overlay.addEventListener('click',e=>{const b=e.target.closest('[data-answer]');if(b)finish(b.dataset.answer==='yes');else if(e.target===overlay)finish(false)});document.body.append(overlay);overlay.querySelector('button').focus()})}

// Partner logo marquee: native horizontal scrolling, seamless wrap, pause during touch.
(function(){
 let frame=0,last=0,pausedUntil=0,viewport=null,track=null,period=0;
 function setup(){
  if(frame)cancelAnimationFrame(frame);frame=0;last=0;
  viewport=document.querySelector('.partners-viewport');track=viewport?.querySelector('.partners-track');
  if(!viewport||!track||!matchMedia('(max-width:700px)').matches)return;
  track.querySelectorAll('[data-partner-clone]').forEach(n=>n.remove());
  const originals=[...track.children];if(!originals.length)return;
  originals.forEach(el=>{let clone=el.cloneNode(true);clone.dataset.partnerClone='1';clone.setAttribute('aria-hidden','true');track.appendChild(clone)});
  const gap=parseFloat(getComputedStyle(track).gap)||0;
  period=originals.reduce((sum,el)=>sum+el.getBoundingClientRect().width+gap,0);
  const pause=()=>{pausedUntil=performance.now()+2400};
  viewport.onpointerdown=pause;viewport.onpointerup=pause;viewport.onwheel=pause;
  if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;
  function tick(now){
   if(!viewport.isConnected||!matchMedia('(max-width:700px)').matches){frame=0;return}
   if(last&&now>pausedUntil){viewport.scrollLeft+=(Math.min(now-last,50)*0.022)}
   if(period&&viewport.scrollLeft>=period)viewport.scrollLeft-=period;
   last=now;frame=requestAnimationFrame(tick)
  }
  frame=requestAnimationFrame(tick)
 }
 window.addEventListener('hashchange',()=>setTimeout(setup,70));
 window.addEventListener('resize',()=>setTimeout(setup,100));
 document.addEventListener('DOMContentLoaded',()=>setTimeout(setup,1100));
})();

// Custom styled select menus; keep original selects for FormData and existing handlers.
function enhanceBzhSelects(){
 document.querySelectorAll('#content select').forEach(sel=>{
  if(sel.closest('.bzh-select'))return;
  const wrap=document.createElement('div');wrap.className='bzh-select';
  if(sel.id==='catFilter')wrap.id='bzh-cat-wrap';
  sel.parentNode.insertBefore(wrap,sel);wrap.appendChild(sel);
  const trigger=document.createElement('button');trigger.type='button';trigger.className='bzh-select-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
  const menu=document.createElement('div');menu.className='bzh-select-options';menu.setAttribute('role','listbox');menu.hidden=true;
  function refresh(){trigger.textContent=sel.selectedOptions[0]?.textContent||'Seçin';menu.replaceChildren();Array.from(sel.options).forEach((opt,i)=>{const b=document.createElement('button');b.type='button';b.className='bzh-select-option';b.textContent=opt.textContent;b.disabled=opt.disabled;b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===sel.selectedIndex));b.onclick=()=>{sel.selectedIndex=i;sel.dispatchEvent(new Event('change',{bubbles:true}));refresh();close()};menu.appendChild(b)})}
  function close(){menu.hidden=true;trigger.setAttribute('aria-expanded','false')}
  trigger.onclick=()=>{const open=menu.hidden;document.querySelectorAll('.bzh-select-options').forEach(x=>{x.hidden=true;x.parentElement.querySelector('.bzh-select-trigger')?.setAttribute('aria-expanded','false')});menu.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(open){const rect=trigger.getBoundingClientRect();menu.style.top=rect.bottom>window.innerHeight-270?'auto':'';menu.style.bottom=rect.bottom>window.innerHeight-270?'calc(100% + 4px)':''}};
  wrap.append(trigger,menu);sel.addEventListener('change',refresh);refresh();
 });
}
document.addEventListener('click',e=>{if(e.target.closest('.bzh-select'))return;document.querySelectorAll('.bzh-select-options').forEach(x=>{x.hidden=true;x.parentElement.querySelector('.bzh-select-trigger')?.setAttribute('aria-expanded','false')})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.bzh-select-options').forEach(x=>{x.hidden=true;x.parentElement.querySelector('.bzh-select-trigger')?.setAttribute('aria-expanded','false')})});

// Admin camera: live square-ish product preview; captured file follows existing WebP optimizer.
let bzhCameraStream=null;
async function closeBzhCamera(){if(bzhCameraStream){bzhCameraStream.getTracks().forEach(t=>t.stop());bzhCameraStream=null}document.getElementById('bzhCameraDialog')?.remove()}
document.addEventListener('click',async e=>{if(e.target.closest('#bzhOpenCamera')){if(!navigator.mediaDevices?.getUserMedia)return toast('Kamera yalnız HTTPS və kamera icazəsi ilə işləyir');const dlg=document.createElement('div');dlg.id='bzhCameraDialog';dlg.className='bzh-camera-dialog';dlg.innerHTML='<div class="bzh-camera-card"><video autoplay muted playsinline></video><div class="actions"><button type="button" class="btn secondary" id="bzhCancelCamera">Bağla</button><button type="button" class="btn" id="bzhTakePhoto">Şəkil çək</button></div></div>';document.body.append(dlg);try{bzhCameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:1280}},audio:false});dlg.querySelector('video').srcObject=bzhCameraStream}catch(err){await closeBzhCamera();toast('Kamera açıla bilmədi: '+err.message)}}else if(e.target.closest('#bzhCancelCamera')||e.target.id==='bzhCameraDialog'){await closeBzhCamera()}else if(e.target.closest('#bzhTakePhoto')){const video=document.querySelector('#bzhCameraDialog video');if(!video?.videoWidth)return;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=900;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,900,900);const scale=Math.min(900/video.videoWidth,900/video.videoHeight);const w=video.videoWidth*scale,h=video.videoHeight*scale;ctx.drawImage(video,(900-w)/2,(900-h)/2,w,h);canvas.toBlob(async blob=>{if(!blob)return;const file=new File([blob],'kamera-mehsul.jpg',{type:'image/jpeg'});const dt=new DataTransfer();dt.items.add(file);const input=document.getElementById('bzhProductImage');if(input){input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}))}await closeBzhCamera()},'image/jpeg',.96)}});
window.addEventListener('pagehide',()=>{if(bzhCameraStream)bzhCameraStream.getTracks().forEach(t=>t.stop())});

/* Android PWA installation: show only when the browser actually offers installation. */
(()=>{let pending=null;const button=()=>document.getElementById('bzhInstall');const standalone=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;const android=()=>/Android/i.test(navigator.userAgent);const sync=()=>{const b=button();if(b)b.hidden=!android()||standalone()||!pending};window.addEventListener('beforeinstallprompt',e=>{if(!android()||standalone())return;e.preventDefault();pending=e;sync()});window.addEventListener('appinstalled',()=>{pending=null;sync()});document.addEventListener('DOMContentLoaded',()=>{sync();button()?.addEventListener('click',async()=>{if(!pending)return;const event=pending;pending=null;sync();try{await event.prompt();await event.userChoice}catch(_){}})});})();
